fn main() {
    let readings = [6, 11, 3, 14, 9];
    let mut count = 0;
    let mut max_reading = readings[0];

    for &reading in readings.iter() {
        if reading > 5 {
            count += 1;
        }
        if reading > max_reading {
            max_reading = reading;
        }
    }

    println!("{}", count);
    println!("{}", max_reading);
}

fn main() {
    let batch = vec![9, 2, 12, 5, 16];
    let mut kept = Vec::new();

    for &num in &batch {
        if num < 10 {
            kept.push(num);
        }
    }

    for &num in &kept {
        println!("{}", num);
    }

    println!("Kept: {}", kept.len());
}

